'use strict';
(()=>{
 const KEY='wolf-console-demo-v3';let db;
 try{db=JSON.parse(localStorage.getItem(KEY));}catch{}if(!db||db.version!==3)db=window.WOLF_CONSOLE_SEED();
 const S={view:'overview',id:'',tab:'current',q:'',filter:'all',page:0,selected:new Set(),days:7,origin:'all'};
 const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const P=()=>db.projects.find(p=>p.id===db.selected)||db.projects[0];const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(db));}catch{toast('Хранилище браузера недоступно. Изменения останутся до обновления страницы.');}};
 const fmt=x=>new Intl.NumberFormat('ru-RU').format(x);const date=x=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',timeZone:'Europe/Moscow'}).format(new Date(x));const now=()=>new Date().toISOString();const uid=k=>k+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);const kb=x=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(x/1024)+' КБ';
 const paths={projects:'<rect x="3" y="4" width="7" height="7"/><rect x="14" y="4" width="7" height="7"/><rect x="3" y="15" width="7" height="6"/><rect x="14" y="15" width="7" height="6"/>',overview:'<path d="M3 11 12 3l9 8v10h-7v-7h-4v7H3z"/>',memory:'<path d="M4 4h6l2 2h8v15H4zM8 11h8M8 15h8"/>',faces:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',skills:'<path d="m13 2-8 12h6l-1 8 9-13h-6z"/>',changes:'<path d="M5 3v12a4 4 0 0 0 4 4h11m-5-5 5 5-5 5M9 7h10m-4-4 4 4-4 4"/>',requests:'<path d="M3 4h18v13H9l-6 4zM7 8h10M7 12h6"/>',metrics:'<path d="M4 3h16v18H4zM8 8h8M8 12h8M8 16h5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>'};
 const icon=n=>'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'+(paths[n]||paths.memory)+'</svg>';document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
 const names={projects:'Все проекты',overview:'Обзор',memory:'Память и документы',faces:'Лица',skills:'Скиллы',changes:'Изменения',requests:'Обращения Стюарду',metrics:'Метрики и источники'};
 const kindName=k=>({note:'Рабочая заметка',lesson:'Урок',rule:'Правило',decision:'Решение',document:'Документ',face:'Лицо',skill:'Скилл',memory:'Память',complaint:'Жалоба',aggregation:'Агрегация',review:'Пересмотр'})[k]||k;
 const originName=x=>({project:'Изменено в проекте',base:'Базовая поставка',global:'Глобальная настройка'})[x]||x;
 const statusName=x=>({active:'Активно',archived:'Архив',superseded:'Заменено',deleted:'Удалено в демо',accepted:'Принято',validate:'На проверке',queued:'В очереди',resolved:'Разрешено',completed:'Завершено'})[x]||x;
 const badge=(s,label)=>'<span class="stamp '+(['active','accepted','resolved','completed'].includes(s)?'green':['validate','queued'].includes(s)?'amber':s==='deleted'?'red':'muted')+'">'+esc(label||statusName(s))+'</span>';
 const btn=(label,action,cls='',extra='')=>'<button class="btn '+cls+'" data-action="'+action+'" '+extra+'>'+label+'</button>';
 const link=(label,action,extra='')=>'<button class="link" data-action="'+action+'" '+extra+'>'+label+'</button>';
 const go=(v,id='')=>{const hash='#'+v+(id?'/'+id:'');if(location.hash===hash){route();}else location.hash=hash;};
 const head=(tag,title,sub,actions='')=>'<div class="page-head"><div><div class="eyebrow">'+tag+'</div><h1>'+title+'</h1><p>'+sub+'</p></div><div class="head-actions">'+actions+'</div></div>';
 const notice=t=>'<div class="notice">'+t+'</div>';
 const liveDocs=()=>P().docs.filter(d=>d.status!=='deleted');const obj=(type,id)=>P()[type==='face'?'faces':'skills'].find(o=>o.id===id);const doc=id=>P().docs.find(d=>d.id===id);const current=o=>o.history.find(h=>h.version===o.version)||o.history.at(-1);
 function markdown(text){let html='',para=[],list=[];const flush=()=>{if(para.length){html+='<p>'+para.join('<br>')+'</p>';para=[];}if(list.length){html+='<ul>'+list.map(x=>'<li>'+x+'</li>').join('')+'</ul>';list=[];}};for(const line of esc(text).split('\n')){const h=line.match(/^(#{1,3}) (.*)$/);if(h){flush();const n=h[1].length+1;html+='<h'+n+'>'+h[2]+'</h'+n+'>';}else if(line.startsWith('- ')){if(para.length)flush();list.push(line.slice(2));}else if(!line.trim()){flush();}else{if(list.length)flush();para.push(line);}}flush();return html;}

 const kpi=(label,n,sub,action)=>'<div class="kpi"><div class="kpi-label">'+label+(action?link('↗',action,'aria-label="Открыть: '+esc(label)+'"'):'')+'</div><strong class="'+(String(n).length>8?'word-value':'')+'">'+n+'</strong><small>'+sub+'</small></div>';
 function objectRoute(type,id,tab='current'){S.tab=tab;go(type==='face'?'faces':'skills',id);}
 function chrome(){const p=P();$('project-select').innerHTML=db.projects.map(x=>'<option value="'+x.id+'" '+(p.id===x.id?'selected':'')+'>'+x.name+'</option>').join('');$('project-path').textContent=p.path;$('breadcrumb').innerHTML='<strong>'+esc(S.view==='projects'?'Глобальный Wolf':p.name)+'</strong><span>/</span>'+names[S.view];$('change-count').textContent=p.changes.length;$('request-count').textContent=p.requests.filter(r=>r.status==='queued').length;document.querySelectorAll('[data-nav]').forEach(e=>{e.classList.toggle('active',e.dataset.nav===S.view);if(e.dataset.nav===S.view)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});}
 function overview(){const p=P(),docs=liveDocs(),validating=[...p.faces,...p.skills].filter(o=>o.status==='validate'),active=docs.filter(d=>d.status==='active'),touched=active.filter(d=>d.reads||d.deliveries),pending=p.requests.filter(r=>r.status==='queued');return '<section class="hero"><div class="hero-copy"><div class="eyebrow">ОРГАНИЗАЦИЯ ПРОЕКТА / '+p.mark+'</div><h1>Память. Поведение.<br>История изменений.</h1><p>'+esc(p.name)+' · '+esc(p.description)+'. Все знания и действующие инструкции проекта — в одном рабочем пространстве.</p><div class="row-actions">'+btn('Открыть память '+icon('arrow'),'nav-memory','brass')+btn('Что изменилось','nav-changes','dark')+'</div></div><div class="hero-aside"><div class="hero-line"><span>Источники проекта</span><strong>DEMO SNAPSHOT</strong></div><div class="hero-line"><span>Лица / скиллы</span><strong>'+p.faces.length+' / '+p.skills.length+'</strong></div><div class="hero-line"><span>Версий на проверке</span><strong>'+validating.length+'</strong></div><div class="hero-line"><span>Обращений в очереди</span><strong>'+pending.length+'</strong></div><div class="hero-foot">ПАМЯТЬ → ЖАЛОБА → МУТАЦИЯ → ОБРАТНАЯ СВЯЗЬ</div></div></section><div class="kpis">'+kpi('Записей памяти',docs.length,active.length+' активных · все типы и документы','nav-memory')+kpi('С обращениями',touched.length+' / '+active.length,'Активные записи · условное окно 7 дней','nav-metrics')+kpi('Изменений инструкций',p.changes.filter(c=>['face','skill'].includes(c.type)).length,'Лица и скиллы · история демопроекта','nav-changes')+kpi('На проверке',validating.length,'Действующие версии с обратной связью','validate')+'</div><div class="section-label"><h2>Требует внимания</h2><span>ОТ НАБЛЮДЕНИЯ К ДЕЙСТВИЮ</span></div><div class="insights"><article class="insight"><small>01 / ПОВЕДЕНИЕ</small><h3>Как изменились инструкции?</h3><p>Границы L2 сужены, методика выбирает достаточный путь. Открой точный текст и основание мутации.</p>'+link('Сравнить лицо L2 →','open-object','data-type="face" data-id="worker-implementer" data-tab="diff"')+'</article><article class="insight"><small>02 / РАБОЧАЯ ПАМЯТЬ</small><h3>Уроки можно объединить</h3><p>Выбери связанные заметки, опиши желаемый итог и передай поручение Стюарду.</p>'+link('Выбрать записи →','aggregation-start')+'</article><article class="insight"><small>03 / ХРАНЕНИЕ</small><h3>Наблюдение тоже занимает место</h3><p>В условном снимке телеметрия занимает больше места, чем память. История знаний выделена отдельно.</p>'+link('Посмотреть состав →','nav-metrics')+'</article></div><div class="grid-wide"><section class="panel"><div class="panel-head"><div><h2>Что меняется в поведении</h2><p>Причина, действующая версия и доступное подтверждение</p></div>'+link('Все изменения →','nav-changes')+'</div>'+p.changes.slice(0,3).map(changeRow).join('')+'</section><section class="panel"><div class="panel-head"><div><h2>Где находится память</h2><p>Текущее состояние, включая архивные записи</p></div></div><div class="bars">'+['note','lesson','rule','decision','document'].map(k=>{const n=docs.filter(d=>d.kind===k).length;return '<div><div class="bar-title"><span>'+kindName(k)+'</span><span>'+n+' ЗАП.</span></div><div class="track"><div style="width:'+(n/docs.length*100)+'%"></div></div></div>';}).join('')+'</div><p class="small-note">Чтение и доставка показывают обращение к памяти. Подтверждённое применение пока неизвестно.</p></section></div>';}
 function projects(){return head('ГЛОБАЛЬНЫЙ WOLF / РЕЕСТР','Один сервис. Несколько проектов.','Выбери проект: документы, инструкции, обращения и изменения откроются в его контексте.')+'<div class="project-grid">'+db.projects.map(p=>'<article class="project-card '+(p.id===db.selected?'selected':'')+'"><div class="project-mark">'+p.mark+'</div><h2>'+p.name+'</h2><p>'+p.description+'</p><code>'+p.path+'</code><div class="project-stats"><div><strong>'+p.docs.filter(d=>d.status!=='deleted').length+'</strong>записей</div><div><strong>'+p.faces.length+'</strong>лиц</div><div><strong>'+p.skills.length+'</strong>скиллов</div></div>'+btn(p.id===db.selected?'Продолжить работу →':'Открыть проект →','switch-project','brass','data-id="'+p.id+'"')+'</article>').join('')+'</div>'+notice('В будущем сервис читает глобальный реестр Wolf. Здесь показаны три независимых демопроекта: действия в одном не меняют остальные.');}
 function filteredDocs(){const q=S.q.toLowerCase();return P().docs.filter(d=>(S.filter==='deleted'?d.status==='deleted':d.status!=='deleted'&&(S.filter==='all'||d.kind===S.filter||S.filter==='unread'&&d.reads+d.deliveries===0||S.filter==='archived'&&d.status==='archived'))&&(!q||(d.title+' '+d.id+' '+d.content).toLowerCase().includes(q)));}
 function docTable(){const list=filteredDocs(),pages=Math.max(1,Math.ceil(list.length/10));S.page=Math.min(S.page,pages-1);return '<div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="select-page" aria-label="Выбрать записи на странице" '+(list.slice(S.page*10,S.page*10+10).length&&list.slice(S.page*10,S.page*10+10).every(d=>S.selected.has(d.id))?'checked':'')+'></th><th>Документ / запись</th><th>Тип и статус</th><th class="numeric">Чтения</th><th class="numeric">Доставки</th></tr></thead><tbody>'+list.slice(S.page*10,S.page*10+10).map(d=>'<tr class="clickable"><td><input type="checkbox" data-select-doc="'+d.id+'" aria-label="Выбрать '+esc(d.title)+'" '+(S.selected.has(d.id)?'checked':'')+'></td><td>'+link(esc(d.title),'open-doc','data-id="'+d.id+'"')+'<small>'+d.id+' · v'+d.revision+' · '+date(d.updated)+'</small></td><td><div style="margin-bottom:6px">'+kindName(d.kind)+'</div>'+badge(d.status)+'</td><td class="numeric">'+d.reads+'</td><td class="numeric">'+d.deliveries+'</td></tr>').join('')+'</tbody></table></div>'+(list.length?'':'<div class="empty">Ничего не найдено. Измени запрос или фильтр.</div>')+'<div class="pagination"><span>'+list.length+' записей · страница '+(S.page+1)+' из '+pages+'</span><div>'+btn('←','page','small','data-delta="-1" '+(S.page===0?'disabled':'')+' aria-label="Предыдущая страница"')+btn('→','page','small','data-delta="1" '+(S.page>=pages-1?'disabled':'')+' aria-label="Следующая страница"')+'</div></div>';}
 function selection(){return S.selected.size?'<div class="selection-bar"><span>Выбрано: '+S.selected.size+'</span>'+btn('Поручить агрегацию','new-aggregation','brass small',S.selected.size<2?'disabled':'')+btn('Попросить пересмотр','new-review','dark small')+link('Снять выбор','clear-selection')+'</div>':'';}
 function memory(){return head('ЗНАНИЯ ПРОЕКТА','Память и документы','Читай, связывай и корректируй знания. Для объединения выбери несколько записей.',btn('+ Добавить запись','new-memory','brass'))+'<div class="filters"><input class="input search" id="memory-search" type="search" placeholder="Поиск по содержанию, названию или ID" aria-label="Поиск по памяти" value="'+esc(S.q)+'"><select class="control" id="memory-filter" aria-label="Фильтр памяти">'+[['all','Все записи'],['note','Рабочие заметки'],['lesson','Уроки'],['rule','Правила'],['decision','Решения'],['document','Документы'],['unread','Без обращений'],['archived','Архив'],['deleted','Удалённые в демо']].map(([k,v])=>'<option value="'+k+'" '+(S.filter===k?'selected':'')+'>'+v+'</option>').join('')+'</select></div><div id="selection">'+selection()+'</div><section class="panel table-panel" id="doc-table">'+docTable()+'</section><p class="small-note">Все документы представлены как память с разным назначением. В демо удаление обратимо через фильтр «Удалённые в демо». Исходники агрегации сохраняются в архиве.</p>';}
 function catalog(type){const items=P()[type==='face'?'faces':'skills'],list=items.filter(o=>(S.filter!=='validate'||o.status==='validate')&&(!S.q||(o.id+' '+o.title+' '+o.description).toLowerCase().includes(S.q.toLowerCase())));return head(type==='face'?'РОЛИ И ПОЛНОМОЧИЯ':'МЕТОДИКИ ВЫПОЛНЕНИЯ',type==='face'?'Лица проекта':'Скиллы проекта',type==='face'?'Какие инструкции определяют поведение агентов и как они изменяются.':'Что делает каждая методика, откуда она взята и какие версии проходят проверку.')+'<div class="filters"><input class="input search" id="catalog-search" aria-label="Поиск инструкций" placeholder="Название, ID или назначение" value="'+esc(S.q)+'"><select class="control" id="catalog-filter" aria-label="Статус инструкций"><option value="all">Все инструкции</option><option value="validate" '+(S.filter==='validate'?'selected':'')+'>На проверке</option></select></div><div class="catalog">'+list.map(o=>'<article class="object-card"><div class="object-top"><span class="tag">'+(o.level||'SKILL')+'</span>'+badge(o.status)+'</div><span class="object-id">'+o.id+'</span><h2>'+o.title+'</h2><p>'+o.description+'</p><div class="badges"><span class="stamp '+(o.origin==='project'?'amber':'muted')+'">'+originName(o.origin)+'</span></div><div class="object-footer"><span>Действует v'+o.version+'</span>'+link('Открыть →','open-object','data-type="'+type+'" data-id="'+o.id+'"')+'</div></article>').join('')+'</div>'+(list.length?'':'<div class="empty">Подходящих инструкций нет.</div>')+notice('Показана итоговая инструкция проекта с учётом происхождения. Применение новой версии в уже работающих сессиях требует отдельного наблюдения.');}
 function diff(o){const versions=o.history,selected=S.compare?versions.find(v=>v.version===S.compare):versions[versions.length-2],latest=current(o);if(!selected||selected.version===latest.version)return notice('Для этой инструкции пока нет двух разных сохранённых версий для сравнения.');const before=selected.content.split('\n'),after=latest.content.split('\n');return '<div class="diff-head"><div><h2>Что именно изменено</h2><p class="small-note">'+esc(latest.reason)+'</p></div><select id="compare-version" class="control" aria-label="Предыдущая версия для сравнения">'+versions.filter(v=>v.version!==latest.version).map(v=>'<option value="'+v.version+'" '+(v.version===selected.version?'selected':'')+'>Сравнить v'+v.version+' → v'+latest.version+'</option>').join('')+'</select></div><div class="diff-grid"><section class="diff-pane old"><div>БЫЛО / v'+selected.version+' · '+date(selected.date)+'</div><pre>'+before.map(l=>'<span class="diff-line '+(l&&!after.includes(l)?'removed':'')+'">'+esc(l||' ')+'</span>').join('')+'</pre></section><section class="diff-pane new"><div>ДЕЙСТВУЕТ / v'+latest.version+' · '+date(latest.date)+'</div><pre>'+after.map(l=>'<span class="diff-line '+(l&&!before.includes(l)?'added':'')+'">'+esc(l||' ')+'</span>').join('')+'</pre></section></div><p class="small-note">Подсвечены строки, отличающиеся по содержанию. Сравнение не является автоматической оценкой качества изменения.</p>';}
 function objectDetail(type,id){const o=obj(type,id);if(!o)return head('ОБЪЕКТ НЕ НАЙДЕН','Инструкция недоступна','Выбери объект в каталоге.',btn('К каталогу','nav-'+(type==='face'?'faces':'skills')));const v=current(o),previous=o.history.filter(h=>h.version!==o.version).at(-1);const statusBox=o.status==='validate'?'<div class="review-box"><div class="badges">'+badge('validate')+'<strong>Версия v'+o.version+' действует в демопроекте и проходит проверку</strong></div><p>Записано отзывов: '+o.feedback.filter(f=>f.ver===o.version).length+'. Отсутствие жалоб не подтверждает улучшение. Решение можно принять после просмотра оснований.</p><div class="row-actions">'+btn('Добавить отзыв','feedback','','data-type="'+type+'" data-id="'+o.id+'"')+btn('Принять версию','accept-version','brass','data-type="'+type+'" data-id="'+o.id+'"')+'</div></div>':'';
 let body;if(S.tab==='diff')body=diff(o);else if(S.tab==='history')body='<section class="panel">'+o.history.slice().reverse().map(h=>'<div class="timeline-row"><span class="node">'+h.version+'</span><div><strong>Версия '+h.version+' · '+esc(h.actor)+'</strong><p>'+esc(h.reason)+'</p><small>'+date(h.date)+'</small></div>'+link(h.version===o.version?'Действует':'Сравнить','compare-to','data-version="'+h.version+'"')+'</div>').join('')+'</section>';else if(S.tab==='feedback')body='<section class="panel"><div class="panel-head"><h2>Обратная связь</h2>'+btn('+ Отзыв','feedback','small','data-type="'+type+'" data-id="'+o.id+'"')+'</div>'+o.feedback.map(f=>'<div class="timeline-row"><span class="node">'+(f.result==='positive'?'✓':'!')+'</span><div><strong>'+esc(f.text)+'</strong><p>Версия '+f.ver+' · '+(f.result==='positive'?'Положительное наблюдение':'Обнаружена проблема')+'</p><small>'+date(f.date)+'</small></div></div>').join('')+(o.feedback.length?'':'<div class="empty">Отзывы пока не записаны. Это неизвестный результат проверки.</div>')+'</section>';else body='<div class="document">'+markdown(v.content)+'</div>';
 return head((type==='face'?'ЛИЦО':'СКИЛЛ')+' / '+o.id,esc(o.title),o.description,btn('Редактировать','edit-object','','data-type="'+type+'" data-id="'+o.id+'"')+btn('Оформить жалобу','complaint','','data-type="'+type+'" data-id="'+o.id+'"'))+'<div class="badges">'+badge(o.status)+'<span class="stamp muted">'+originName(o.origin)+'</span><span class="tag">Действует v'+o.version+'</span></div>'+statusBox+'<div class="tabs">'+[['current','Действующий текст'],['diff','Сравнение'],['history','Версии'],['feedback','Обратная связь']].map(([k,v])=>'<button class="tab '+(S.tab===k?'active':'')+'" data-action="object-tab" data-tab="'+k+'">'+v+'</button>').join('')+'</div><div class="detail-grid"><div>'+body+'</div><aside class="properties"><h3>Контекст инструкции</h3><div class="property"><small>ИСТОЧНИК</small>'+originName(o.origin)+'<p class="small-note">'+(o.origin==='project'?'Проектное изменение поверх базовой инструкции.':o.origin==='global'?'Наследуется из глобального Wolf.':'Установлено из базового набора.')+'</p></div><div class="property"><small>ПОСЛЕДНЕЕ ИЗМЕНЕНИЕ</small>'+esc(v.actor)+' · '+date(v.date)+'<p class="small-note">'+esc(v.reason)+'</p></div><div class="property"><small>ОСНОВАНИЕ</small>'+(o.complaint?link('Жалоба '+o.complaint+' →','open-request','data-id="'+o.complaint+'"'):'Связь с обращением не записана')+'</div><div class="property"><small>ДОСТАВКА ДЕЙСТВУЮЩЕЙ ВЕРСИИ</small>'+(o.uses===null?'Неизвестно':o.uses+' наблюдений в демо')+'<p class="small-note">Полнота покрытия неизвестна. Текущий текст не доказывает, что его получили все открытые сессии.</p></div><div class="property"><small>'+(type==='face'?'СВЯЗАННЫЕ СКИЛЛЫ':'ИСПОЛЬЗУЮЩИЕ ЛИЦА')+'</small>'+(type==='face'?o.skills.map(s=>link(s,'open-object','data-type="skill" data-id="'+s+'"')).join(''):P().faces.filter(f=>f.skills.includes(o.id)).map(f=>link(f.title,'open-object','data-type="face" data-id="'+f.id+'"')).join('')||'Связи не записаны')+'</div>'+(previous?'<div class="property">'+btn('Вернуть текст v'+previous.version,'rollback','','data-type="'+type+'" data-id="'+o.id+'"')+'<p class="small-note">Возврат создаст новую запись истории.</p></div>':'')+'</aside></div>';}
 function changeRow(c){return '<div class="timeline-row"><span class="node">'+({face:'F',skill:'S',memory:'M',aggregation:'A'})[c.type]+'</span><div>'+link(esc(c.title),'open-change','data-id="'+c.id+'"')+'<p>'+esc(c.summary)+'</p><small>'+date(c.date)+' · '+esc(c.actor)+' · '+kindName(c.type)+(c.to?' · v'+c.from+' → v'+c.to:'')+'</small></div>'+badge(c.actor.startsWith('Стюард')?'validate':'active',c.actor.startsWith('Стюард')?'МУТАЦИЯ':'ПРАВКА')+'</div>';}
 function changes(){const list=P().changes.filter(c=>(S.filter==='all'||S.filter===c.type)&&(!S.q||(c.title+' '+c.summary+' '+c.actor).toLowerCase().includes(S.q.toLowerCase())));return head('ЭВОЛЮЦИЯ ОРГАНИЗАЦИИ','Что изменилось в проекте','Лица, скиллы и память: от причины изменения до текста и результата.')+'<div class="chain"><div><small>01 / ОСНОВАНИЕ</small><strong>Жалоба или наблюдение</strong><p>Почему понадобилось изменение и кто его запросил.</p></div><div><small>02 / ВМЕШАТЕЛЬСТВО</small><strong>Точное изменение</strong><p>Автор, объект, версии и предполагаемое изменение поведения.</p></div><div><small>03 / ПРОВЕРКА</small><strong>Доступная обратная связь</strong><p>Где версия доставлена и какие наблюдения записаны после неё.</p></div></div><div class="chips">'+[['all','Все изменения'],['face','Лица'],['skill','Скиллы'],['memory','Память'],['aggregation','Агрегации']].map(([k,v])=>'<button class="chip '+(S.filter===k?'active':'')+'" data-action="change-filter" data-value="'+k+'" aria-pressed="'+(S.filter===k)+'">'+v+'</button>').join('')+'</div><section class="panel">'+list.map(changeRow).join('')+(list.length?'':'<div class="empty">Изменений этого вида пока нет.</div>')+'</section>';}
 function requests(){return head('ОБРАТНАЯ СВЯЗЬ И ПОРУЧЕНИЯ','Обращения Стюарду','Жалоба фиксирует проблему. Поручение задаёт ожидаемый результат работы.',btn('+ Новое обращение','new-request','brass'))+P().requests.slice().reverse().map(r=>'<article class="requests-row"><div><div class="badges"><span class="tag">'+kindName(r.kind)+'</span><small>'+r.id+' · '+date(r.date)+'</small></div><h3 style="margin-top:12px">'+link(esc(r.title),'open-request','data-id="'+r.id+'"')+'</h3><p>'+esc(r.body)+'</p><small>'+esc(r.actor)+' · связано объектов: '+r.targets.length+'</small></div><div class="badges">'+badge(r.status)+link('Открыть →','open-request','data-id="'+r.id+'"')+'</div></article>').join('')+notice('В этом прототипе нет подключения к агентам. Поручения остаются в демоочереди. Для агрегации можно явно проиграть пример выполнения и посмотреть результат.');}
 function metrics(){const d=window.WOLF_DEMO,docs=liveDocs(),mem=docs.reduce((s,m)=>s+m.bytes,0),scale=docs.length/72,logs=Math.round(539264*scale),rs=docs.reduce((s,m)=>s+m.reads,0),ins=docs.reduce((s,m)=>s+m.deliveries,0);const ms=d.metrics.filter(m=>S.origin==='all'||m.origin===S.origin);return head('НАБЛЮДАЕМОСТЬ / УСЛОВНЫЕ ДАННЫЕ','Работа системы и цена наблюдения','Текущее состояние проекта и пример активности. Каждый показатель имеет источник и ограничение.',btn('Экспорт сводки','export'))+'<div class="kpis">'+kpi('Чтений памяти',rs,'Условное окно 7 дней')+kpi('Доставок в контекст',ins,'Считаются отдельно от чтений')+kpi('Применение памяти','Неизвестно','Подтверждённый источник не подключён')+kpi('Расходы Стюарда','Нет данных','Нет достаточной атрибуции')+'</div><div class="grid2"><section class="panel"><div class="panel-head"><div><h2>Объём по назначению</h2><p>Память и служебные данные на дату снимка</p></div></div><div class="bars">'+[['Память объектов',mem],['История изменений',Math.round(117760*scale)],['Связи объектов',Math.round(32768*scale)],['Телеметрия, включая архив',logs]].map(([n,b])=>'<div><div class="bar-title"><span>'+n+'</span><span>'+kb(b)+'</span></div><div class="track"><div style="width:'+b/Math.max(mem,logs)*100+'%"></div></div></div>').join('')+'</div>'+notice('Телеметрия в этом примере занимает '+(logs/mem).toFixed(1).replace('.',',')+' × объёма памяти. История изменений и связи — самостоятельные данные для происхождения и восстановления.')+'</section><section class="panel"><div class="panel-head"><div><h2>Изменения за неделю</h2><p>Условные операции, без оценки качества</p></div></div><div class="chart">'+[3,2,5,1,4,7,2].map(n=>'<div class="chart-col"><span>'+n+'</span><i style="height:'+n*12+'px"></i></div>').join('')+'</div><div class="chart-labels">'+['28.10','29.10','30.10','31.10','01.11','02.11','03.11'].map(n=>'<span>'+n+'</span>').join('')+'</div><p class="small-note">Образец визуализации потока событий. Текущий состав памяти и поток изменений — разные показатели.</p></section></div><div class="grid2"><section class="panel"><h2>Скиллы и процессы</h2><p class="small-note">Вызовы skill наблюдаемы. Чтение напрямую может обходить сбор. Загрузка инструкции не подтверждает соблюдение процесса.</p>'+notice('Для этапов процесса нужен источник: TASK/thread → этап → результат/evidence. Повторные выполнения задач для оценки не требуются.')+'</section><section class="panel"><h2>Что добавляем к сбору</h2><p class="small-note">Адресные версии инструкций, происхождение вмешательства, связи с жалобой, редкие снимки состава и размеров.</p>'+notice('Сбор должен оставаться ограниченным по объёму и стоимости. Неизвестные значения сохраняются неизвестными.')+'</section></div><div class="section-label"><h2>Каталог показателей</h2><span>Срез источников WOLF 2.25.1</span></div><div class="chips"><button class="chip '+(S.origin==='all'?'active':'')+'" data-action="origin-filter" data-value="all">Все ('+d.metrics.length+')</button>'+Object.entries(d.origins).map(([k,v])=>'<button class="chip '+(S.origin===k?'active':'')+'" data-action="origin-filter" data-value="'+k+'">'+v.label+'</button>').join('')+'</div><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Показатель</th><th>Вопрос</th><th>Готовность</th></tr></thead><tbody>'+ms.map(m=>'<tr><td>'+link(m.name,'metric','data-id="'+m.id+'"')+'</td><td>'+m.question+'</td><td><span class="origin '+m.origin+'">'+d.origins[m.origin].label+'</span></td></tr>').join('')+'</tbody></table></div></section>';}
 function render(){chrome();let html=({projects,overview,memory,changes,requests,metrics}[S.view]||(()=>catalog(S.view==='faces'?'face':'skill')))();if(S.id&&['faces','skills'].includes(S.view))html=objectDetail(S.view==='faces'?'face':'skill',S.id);$('view').innerHTML=html;}
 function route(){const [v,id]=location.hash.slice(1).split('/');if(S.view!==v||S.id!==(id||'')){S.q='';S.filter='all';S.page=0;S.compare=null;if(!S.keepTab)S.tab='current';}S.keepTab=false;S.view=names[v]?v:'overview';S.id=id||'';closeDrawer();render();window.scrollTo(0,0);}
 let focusOrigin=null,toastTimer;
 function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
 function drawer(label,html){if($('drawer').hidden)focusOrigin=document.activeElement;$('drawer-label').textContent=label;$('drawer-body').innerHTML=html;$('drawer').hidden=false;$('overlay').hidden=false;document.body.style.overflow='hidden';document.querySelector('.shell').inert=true;$('drawer').scrollTop=0;$('close-drawer').focus();}
 function closeDrawer(){const open=!$('drawer').hidden;$('drawer').hidden=true;$('overlay').hidden=true;document.body.style.overflow='';document.querySelector('.shell').inert=false;if(open&&focusOrigin?.isConnected)focusOrigin.focus();}
 function docDrawer(id){const d=doc(id);if(!d)return;drawer('ПАМЯТЬ / '+d.id,'<h2 id="drawer-title">'+esc(d.title)+'</h2><div class="badges">'+badge(d.status)+'<span class="tag">'+kindName(d.kind)+' · v'+d.revision+'</span></div><p class="lead">'+d.reads+' чтений · '+d.deliveries+' доставок. Применение неизвестно.</p><div class="row-actions">'+(d.status==='deleted'?btn('Восстановить в демо','restore-doc','brass','data-id="'+d.id+'"'):btn('Редактировать','edit-doc','','data-id="'+d.id+'"')+btn('Оформить жалобу','complaint','','data-id="'+d.id+'"')+btn('Удалить','delete-doc','','data-id="'+d.id+'"'))+'</div><div class="document" style="margin-top:20px">'+markdown(d.content)+'</div>'+(d.sources.length?'<h3>Исходники</h3>'+d.sources.map(id=>'<div class="property">'+link(esc(doc(id)?.title||id),'open-doc','data-id="'+id+'"')+'</div>').join(''):'')+'<p class="small-note">Документ демонстрационный. Редактирование создаёт запись истории проекта.</p>');}
 function changeDrawer(id){const c=P().changes.find(c=>c.id===id);if(!c)return;drawer('ИСТОРИЯ / '+c.id,'<h2 id="drawer-title">'+esc(c.title)+'</h2><div class="badges"><span class="tag">'+kindName(c.type)+'</span><span class="stamp muted">'+esc(c.actor)+' · '+date(c.date)+'</span></div><h3>Что меняется</h3><p class="lead">'+esc(c.summary)+'</p><h3>Почему</h3><p class="lead">'+esc(c.reason)+'</p><h3>Основание</h3>'+(c.request?btn('Открыть обращение '+c.request,'open-request','','data-id="'+c.request+'"'):'<p class="lead">'+esc(c.actor==='Пользователь'?'Ручное действие пользователя.':'Отдельное обращение не связано.')+'</p>')+'<h3>Изменённый объект</h3>'+(c.type==='face'||c.type==='skill'?btn('Открыть версии и сравнение','open-object','brass','data-type="'+c.type+'" data-id="'+c.target+'" data-tab="diff"'):btn('Открыть запись','open-doc','brass','data-id="'+c.target+'"'))+notice('Зафиксирован факт изменения и его назначение. Это ещё не доказательство улучшения качества или экономии.'));}
 function targetLink(id){const d=doc(id);if(d)return link(esc(d.title),'open-doc','data-id="'+id+'"');const f=P().faces.find(x=>x.id===id),s=P().skills.find(x=>x.id===id),o=f||s;return o?link(esc(o.title)+' · '+o.id,'open-object','data-type="'+(f?'face':'skill')+'" data-id="'+id+'"'):esc(id);}
 function requestDrawer(id){const r=P().requests.find(r=>r.id===id);if(!r)return;drawer('ОБРАЩЕНИЕ / '+r.id,'<h2 id="drawer-title">'+esc(r.title)+'</h2><div class="badges">'+badge(r.status)+'<span class="tag">'+kindName(r.kind)+'</span></div><p class="small-note">'+date(r.date)+' · '+esc(r.actor)+'</p><h3>Постановка</h3><p class="lead">'+esc(r.body)+'</p><h3>Связанные объекты</h3>'+r.targets.map(id=>'<div class="property">'+targetLink(id)+'</div>').join('')+(r.result?'<h3>Результат</h3><p class="lead">'+esc(r.result)+'</p>':'<p class="lead">Результат пока не записан. Поручение находится в демоочереди.</p>')+P().changes.filter(c=>c.request===r.id).map(c=>'<div class="property">'+link(esc(c.title),'open-change','data-id="'+c.id+'"')+'</div>').join('')+(r.kind==='aggregation'&&r.status==='queued'?notice('Можно проиграть условное выполнение: создать итоговую запись, связать исходники и перевести их в архив. Агент не запускается.')+btn('Смоделировать агрегацию','simulate-aggregation','brass','data-id="'+r.id+'"'):'')+notice('Демонстрационная история. Новые обращения не отправляются реальному Стюарду.'));}
 function field(label,id,value='',type='text',extra=''){return '<div class="form-field"><label for="'+id+'">'+label+'</label>'+(type==='textarea'?'<textarea id="'+id+'" '+extra+'>'+esc(value)+'</textarea>':'<input id="'+id+'" type="'+type+'" value="'+esc(value)+'" '+extra+'>')+'</div>';}
 function formFoot(text){return '<p class="form-error" id="form-error" role="alert"></p><div class="form-foot">'+btn('Отмена','close')+'<button type="submit" class="btn brass">'+text+'</button></div>';}
 function memoryForm(id){const d=id?doc(id):null;drawer(d?'РЕДАКТИРОВАНИЕ / ПАМЯТЬ':'НОВАЯ ЗАПИСЬ','<h2 id="drawer-title">'+(d?'Скорректировать запись':'Добавить знание')+'</h2><p class="lead">Изменение сохранится в выбранном демопроекте «'+esc(P().name)+'».</p><form id="memory-form" data-id="'+(d?.id||'')+'" data-revision="'+(d?.revision||0)+'">'+field('Название','doc-title',d?.title||'','text','required maxlength="180"')+'<div class="form-field"><label for="doc-kind">Назначение</label><select id="doc-kind">'+['note','lesson','rule','decision','document'].map(k=>'<option value="'+k+'" '+(d?.kind===k?'selected':'')+'>'+kindName(k)+'</option>').join('')+'</select></div>'+field('Содержание (Markdown)','doc-content',d?.content||'','textarea','required class="code"')+field('Основание изменения','doc-reason','','text','required placeholder="Что и почему меняем"')+formFoot(d?'Сохранить демоверсию':'Добавить в демопроект')+'</form>');}
 function objectForm(type,id){const o=obj(type,id);if(!o)return;drawer('РЕДАКТИРОВАНИЕ ИНСТРУКЦИИ','<h2 id="drawer-title">'+esc(o.title)+' · новая версия</h2>'+notice('Правка создаст проектную версию со статусом «На проверке». Покрытие её доставки останется неизвестным.')+'<form id="object-form" data-type="'+type+'" data-id="'+id+'" data-version="'+o.version+'">'+field('Текст действующей инструкции','object-content',current(o).content,'textarea','required class="code"')+field('Как должно измениться поведение','object-reason','','textarea','required placeholder="Кратко опиши смысл и основание изменения"')+formFoot('Сохранить новую демоверсию')+'</form>');}
 function requestForm(kind='complaint',targets=[]){if(kind==='aggregation'&&targets.length<2){toast('Выбери минимум две активные записи для агрегации.');return;}const t=targets.filter(Boolean);drawer('НОВОЕ ОБРАЩЕНИЕ','<h2 id="drawer-title">'+(kind==='aggregation'?'Поручить агрегацию':kind==='review'?'Попросить пересмотр':'Оформить жалобу')+'</h2><p class="lead">Проект: '+esc(P().name)+'. Обращение будет сохранено в демоочереди.</p><form id="request-form" data-kind="'+kind+'" data-targets="'+esc(JSON.stringify(t))+'">'+field('Краткое название','request-title',kind==='aggregation'?'Объединить уроки о выполнении частных задач':kind==='review'?'Пересмотреть выбранные записи':'','text','required maxlength="180"')+field(kind==='complaint'?'Что произошло и что ожидалось':'Какой результат нужен','request-body',kind==='aggregation'?'Сформировать одно связное знание без потери существенных условий и оснований. Сохранить связи с исходниками.':'','textarea','required')+(t.length?'<h3>Связанные объекты ('+t.length+')</h3>'+t.map(id=>'<div class="property">'+esc(doc(id)?.title||id)+'</div>').join(''):notice('Общее обращение по проекту. Из карточки документа, лица или скилла можно создать адресную жалобу.'))+formFoot('Добавить в демоочередь')+'</form>');}
 function feedbackForm(type,id){const o=obj(type,id);drawer('ОБРАТНАЯ СВЯЗЬ / v'+o.version,'<h2 id="drawer-title">Наблюдение по версии</h2><p class="lead">'+esc(o.title)+' · действующая v'+o.version+'</p><form id="feedback-form" data-type="'+type+'" data-id="'+id+'" data-version="'+o.version+'"><div class="form-field"><label for="feedback-result">Характер наблюдения</label><select id="feedback-result"><option value="positive">Положительное наблюдение</option><option value="negative">Обнаружена проблема</option></select></div>'+field('Наблюдение и основание','feedback-text','','textarea','required placeholder="Что произошло, в какой задаче и почему это связано с инструкцией"')+formFoot('Сохранить отзыв')+'</form>'+notice('Отзыв относится к конкретной версии. Один отзыв не доказывает общее улучшение.'));}
 function addChange(c){P().changes.unshift({id:uid('chg'),date:now(),actor:'Пользователь',...c});}
 function newVersion(o,content,reason){const before=o.version;o.version=Math.max(...o.history.map(v=>v.version))+1;o.history.push({version:o.version,date:now(),actor:'Пользователь',reason,content});o.origin='project';o.status='validate';o.uses=null;o.complaint=null;addChange({type:o.type,target:o.id,title:'Изменена инструкция: '+o.title,summary:reason,reason,from:before,to:o.version});}
 function simulateAggregation(id){const r=P().requests.find(r=>r.id===id);if(!r||r.status!=='queued')return;const src=r.targets.map(doc).filter(d=>d&&d.status!=='deleted');if(src.length<2){toast('Нужно минимум два доступных исходника.');return;}const d={id:uid('doc'),title:r.title.replace(/^Объединить/i,'Агрегат:'),kind:'lesson',status:'active',memory_class:'canonical',revision:1,reads:0,deliveries:0,bytes:1800,updated:now(),sources:src.map(d=>d.id),content:'# '+r.title+'\n\n## Итоговое знание\nПеред повторным действием выясни причину. Выполняй ограниченное поручение, выбирай достаточную проверку и возвращай вопрос L1 при выходе за границы задачи.\n\n## Область применения\nЧастные задачи L2 и повторные проверки. Это условный результат демонстрации, а не работа агента.\n\n## Основания\n'+src.map(d=>'- '+d.id+' / '+d.title).join('\n')};P().docs.unshift(d);src.forEach(d=>{d.status='archived';d.revision++;d.updated=now();});r.status='completed';r.result='Демоагрегация завершена: создан '+d.id+', '+src.length+' исходника сохранены в архиве.';r.targets.push(d.id);addChange({actor:'Стюард (симуляция)',type:'aggregation',target:d.id,title:'Смоделировано объединение '+src.length+' записей',summary:'Создан итоговый урок; исходники связаны и архивированы.',reason:r.body,request:r.id});S.selected.clear();persist();render();requestDrawer(r.id);toast('Демоагрегация завершена. Можно открыть итог и исходники.');}
 function metricDrawer(id){const m=window.WOLF_DEMO.metrics.find(m=>m.id===id);if(!m)return;drawer('ПАСПОРТ ПОКАЗАТЕЛЯ','<h2 id="drawer-title">'+m.name+'</h2><span class="origin '+m.origin+'">'+window.WOLF_DEMO.origins[m.origin].label+'</span><p class="lead">'+m.question+'</p><h3>Как считается</h3><p class="lead">'+m.formula+'</p><h3>Имеющийся источник · срез 2.25.1</h3><p class="lead">'+m.current+'</p><p class="lead">'+m.source+'</p>'+notice(m.limit)+'<p class="small-note">Готовность метрик перенесена из первого прототипа. Текущая демоверсия не подключена к исходникам проекта и не выполняет эти расчёты над рабочими журналами.</p>');}
 function help(){drawer('КАК СМОТРЕТЬ ПРОТОТИП','<h2 id="drawer-title">От проекта до изменения поведения</h2><p class="lead">Это интерактивный образ будущего локального сервиса. Данные условные, изменения сохраняются только в браузере.</p>'+[['Выбери проект','Реестр и переключатель слева открывают отдельные наборы знаний и инструкций.'],['Посмотри мутацию','Лица → Воркер реализации → Сравнение. Открой жалобу, затем обратную связь по конкретной версии.'],['Поработай с памятью','Найди документ, прочитай его или скорректируй. Выбери две заметки и поручай агрегацию.'],['Проследи результат','В обращении агрегации нажми «Смоделировать агрегацию». Появится итоговая запись со связями, исходники уйдут в архив.'],['Проверь источник показателя','Раздел метрик показывает границы наблюдения, размеры и паспорта существующих и предложенных показателей.']].map(([a,b],i)=>'<div class="guide"><span>0'+(i+1)+'</span><div><strong>'+a+'</strong><p>'+b+'</p></div></div>').join('')+'<p class="small-note">Сброс демоданных доступен внизу боковой панели. Реальные агенты, документы и реестр Wolf не подключены.</p>');}
 function createMenu(){drawer('СОЗДАТЬ В ПРОЕКТЕ','<h2 id="drawer-title">Что добавим в '+esc(P().name)+'?</h2><div class="guide"><span>01</span><div><h3>Знание или документ</h3><p>Рабочая заметка, урок, правило, решение.</p>'+btn('Добавить запись','new-memory','brass')+'</div></div><div class="guide"><span>02</span><div><h3>Жалоба</h3><p>Проблема, ожидаемое поведение и основание.</p>'+btn('Оформить жалобу','new-request')+'</div></div><div class="guide"><span>03</span><div><h3>Поручение Стюарду</h3><p>Выбери несколько записей в памяти для адресного пересмотра или агрегации.</p>'+btn('Перейти к выбору','aggregation-start')+'</div></div>');}
 function reset(){drawer('СБРОС ДЕМОНСТРАЦИИ','<h2 id="drawer-title">Вернуть исходный пример?</h2><p class="lead">Будут сброшены только изменения этого прототипа в браузере: заметки, версии и демообращения. Рабочие проекты не подключены.</p><div class="form-foot">'+btn('Отмена','close')+btn('Сбросить демоданные','confirm-reset','brass')+'</div>');}
 function dispatch(el){const a=el.dataset.action,id=el.dataset.id,type=el.dataset.type;if(a.startsWith('nav-')){S.selected.clear();go(a.slice(4));return;}
 switch(a){
 case 'switch-project':db.selected=id;S.selected.clear();persist();go('overview');render();break;
 case 'open-doc':docDrawer(id);break;
 case 'open-object':S.tab=el.dataset.tab||'current';S.keepTab=true;closeDrawer();go(type==='face'?'faces':'skills',id);break;
 case 'open-change':changeDrawer(id);break;
 case 'open-request':requestDrawer(id);break;
 case 'metric':metricDrawer(id);break;
 case 'validate':S.filter='validate';go('faces');S.filter='validate';render();break;
 case 'object-tab':S.tab=el.dataset.tab;render();break;
 case 'compare-to':S.compare=Number(el.dataset.version);S.tab='diff';render();break;
 case 'change-filter':S.filter=el.dataset.value;render();break;
 case 'origin-filter':S.origin=el.dataset.value;render();break;
 case 'page':S.page+=Number(el.dataset.delta);$('doc-table').innerHTML=docTable();break;
 case 'clear-selection':S.selected.clear();$('selection').innerHTML=selection();$('doc-table').innerHTML=docTable();break;
 case 'aggregation-start':closeDrawer();S.q='';S.filter='note';S.page=0;go('memory');S.filter='note';render();toast('Отметь две или больше заметок, затем нажми «Поручить агрегацию».');break;
 case 'new-aggregation':requestForm('aggregation',[...S.selected]);break;
 case 'new-review':requestForm('review',[...S.selected]);break;
 case 'new-request':requestForm();break;
 case 'complaint':requestForm('complaint',[id]);break;
 case 'new-memory':memoryForm();break;
 case 'edit-doc':memoryForm(id);break;
 case 'delete-doc':{const d=doc(id);drawer('УДАЛЕНИЕ В ДЕМОНСТРАЦИИ','<h2 id="drawer-title">Удалить «'+esc(d.title)+'»?</h2><p class="lead">Запись исчезнет из рабочего списка демопроекта. Её можно восстановить через фильтр удалённых записей.</p><div class="form-foot">'+btn('Отмена','open-doc','','data-id="'+id+'"')+btn('Удалить демозапись','confirm-delete','signal','data-id="'+id+'"')+'</div>');break;}
 case 'confirm-delete':{const d=doc(id);d.beforeDelete=d.status;d.status='deleted';d.revision++;addChange({type:'memory',target:id,title:'Удалена запись: '+d.title,summary:'Запись убрана из рабочего списка демопроекта.',reason:'Ручное удаление пользователя.'});S.selected.delete(id);persist();closeDrawer();render();toast('Демозапись удалена. Доступно восстановление.');break;}
 case 'restore-doc':{const d=doc(id);d.status=d.beforeDelete||'active';d.revision++;addChange({type:'memory',target:id,title:'Восстановлена запись: '+d.title,summary:'Возвращён прежний статус записи.',reason:'Ручное восстановление в демо.'});persist();render();docDrawer(id);break;}
 case 'edit-object':objectForm(type,id);break;
 case 'feedback':feedbackForm(type,id);break;
 case 'accept-version':{const o=obj(type,id);o.status='accepted';addChange({type:o.type,target:id,title:'Принята версия: '+o.title,summary:'Пользователь завершил проверку версии v'+o.version+'.',reason:'Решение пользователя после просмотра инструкции и оснований.',from:o.version,to:o.version});persist();render();toast('Демоверсия принята. Решение записано в историю.');break;}
 case 'rollback':{const o=obj(type,id),prev=o.history.filter(h=>h.version!==o.version).at(-1);drawer('ВОЗВРАТ ТЕКСТА ИНСТРУКЦИИ','<h2 id="drawer-title">Вернуть текст v'+prev.version+'?</h2><p class="lead">Будет создана новая проектная версия с текстом прежней инструкции. История изменений сохранится; статус новой версии — «На проверке».</p><div class="form-foot">'+btn('Отмена','close')+btn('Создать версию возврата','confirm-rollback','brass','data-type="'+type+'" data-id="'+id+'" data-version="'+prev.version+'"')+'</div>');break;}
 case 'confirm-rollback':{const o=obj(type,id),prev=o.history.find(v=>v.version===Number(el.dataset.version));newVersion(o,prev.content,'Пользователь вернул текст версии v'+prev.version+'.');persist();closeDrawer();S.tab='diff';S.compare=null;render();toast('Создана новая демоверсия с прежним текстом.');break;}
 case 'simulate-aggregation':simulateAggregation(id);break;
 case 'close':closeDrawer();break;
 case 'confirm-reset':db=window.WOLF_CONSOLE_SEED();S.selected.clear();persist();closeDrawer();S.tab='current';go('overview');render();toast('Исходные демоданные восстановлены.');break;
 case 'export':{const p=P(),data={mode:'demonstration_only',project:{id:p.id,name:p.name},exportedAt:now(),counts:{memory:liveDocs().length,faces:p.faces.length,skills:p.skills.length,changes:p.changes.length,pendingRequests:p.requests.filter(r=>r.status==='queued').length},unknown:{applied:null,stewardCost:null,processCompliance:null},metricDefinitions:window.WOLF_DEMO.metrics};const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const e=document.createElement('a');e.href=u;e.download='wolf-console-'+p.id+'-demo.json';e.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Демонстрационная сводка экспортирована.');break;}
 }
 }
 document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)dispatch(el);});
 document.addEventListener('input',e=>{if(e.target.id==='memory-search'){S.q=e.target.value;S.page=0;$('doc-table').innerHTML=docTable();}if(e.target.id==='catalog-search'){S.q=e.target.value;const cursor=e.target.selectionStart;render();$('catalog-search').focus();$('catalog-search').setSelectionRange(cursor,cursor);}});
 document.addEventListener('change',e=>{
  if(e.target.dataset.selectDoc){const id=e.target.dataset.selectDoc;e.target.checked?S.selected.add(id):S.selected.delete(id);$('selection').innerHTML=selection();return;}
  if(e.target.id==='select-page'){filteredDocs().slice(S.page*10,S.page*10+10).forEach(d=>e.target.checked?S.selected.add(d.id):S.selected.delete(d.id));$('selection').innerHTML=selection();$('doc-table').innerHTML=docTable();return;}
  if(e.target.id==='memory-filter'||e.target.id==='catalog-filter'){S.filter=e.target.value;S.page=0;render();}
  if(e.target.id==='compare-version'){S.compare=Number(e.target.value);render();}
 });
 document.addEventListener('submit',e=>{const f=e.target;if(!['memory-form','object-form','request-form','feedback-form'].includes(f.id))return;e.preventDefault();
  const fail=t=>{$('form-error').textContent=t;};
  if(f.id==='memory-form'){
   const title=$('doc-title').value.trim(),content=$('doc-content').value.trim(),reason=$('doc-reason').value.trim();if(!title||!content||!reason)return fail('Заполни название, содержание и основание.');
   const id=f.dataset.id,old=id?doc(id):null;if(old&&old.revision!==Number(f.dataset.revision))return fail('Запись изменилась после открытия. Открой актуальную версию перед сохранением.');
   const d=old||{id:uid('doc'),status:'active',revision:0,reads:0,deliveries:0,sources:[]};const before=d.revision;Object.assign(d,{title,content,kind:$('doc-kind').value,memory_class:['rule','decision'].includes($('doc-kind').value)?'canonical':'working',revision:before+1,bytes:new TextEncoder().encode(content).length,updated:now()});if(!old)P().docs.unshift(d);addChange({type:'memory',target:d.id,title:(old?'Изменена запись: ':'Добавлена запись: ')+title,summary:reason,reason,from:before,to:d.revision});persist();render();docDrawer(d.id);toast('Демозапись сохранена.');
  }
  if(f.id==='object-form'){
   const o=obj(f.dataset.type,f.dataset.id),content=$('object-content').value.trim(),reason=$('object-reason').value.trim();if(o.version!==Number(f.dataset.version))return fail('Инструкция изменилась. Открой актуальную версию.');if(!content||!reason)return fail('Нужны текст и смысл изменения.');if(content===current(o).content)return fail('Текст не изменился. Новая версия не требуется.');newVersion(o,content,reason);persist();closeDrawer();S.tab='diff';S.compare=null;render();toast('Проектная демоверсия сохранена и ожидает проверки.');
  }
  if(f.id==='request-form'){
   const title=$('request-title').value.trim(),body=$('request-body').value.trim();if(!title||!body)return fail('Опиши название и содержание обращения.');const r={id:uid('req'),kind:f.dataset.kind,title,body,targets:JSON.parse(f.dataset.targets),status:'queued',date:now(),actor:'Пользователь',result:null};P().requests.push(r);persist();S.selected.clear();render();requestDrawer(r.id);toast('Обращение добавлено в демоочередь.');
  }
  if(f.id==='feedback-form'){
   const o=obj(f.dataset.type,f.dataset.id),text=$('feedback-text').value.trim();if(!text)return fail('Нужно наблюдение с основанием.');o.feedback.push({ver:Number(f.dataset.version),result:$('feedback-result').value,text,date:now()});persist();closeDrawer();S.tab='feedback';render();toast('Отзыв сохранён для версии v'+f.dataset.version+'.');
  }
 });
 $('project-select').addEventListener('change',e=>{db.selected=e.target.value;S.selected.clear();persist();closeDrawer();go('overview');render();});
 $('close-drawer').addEventListener('click',closeDrawer);$('overlay').addEventListener('click',closeDrawer);$('new-action').addEventListener('click',createMenu);$('help').addEventListener('click',help);$('reset-demo').addEventListener('click',reset);
 try{document.documentElement.classList.toggle('dark',localStorage.getItem('wolf-console-theme')==='dark');}catch{}
 $('theme').addEventListener('click',()=>{const dark=document.documentElement.classList.toggle('dark');try{localStorage.setItem('wolf-console-theme',dark?'dark':'light');}catch{};});
 document.addEventListener('keydown',e=>{if($('drawer').hidden)return;if(e.key==='Escape'){e.preventDefault();closeDrawer();}if(e.key==='Tab'){const f=[...$('drawer').querySelectorAll('button,a[href],input,textarea,select')].filter(x=>!x.disabled&&!x.hidden);const first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
 window.addEventListener('hashchange',route);route();
})();
